const huffValue = c => c >= 97 ? c - 71 : c >= 65 && c <= 90 ? c - 65 : c >= 48 && c <= 57 ? c + 4 : c === 36 ? 62 : 63;

const f64Bytes = new Uint8Array(8);
const f64View = new Float64Array(f64Bytes.buffer);
const fromF64Hex = hex => {
  for (let i = 0; i < 8; i++) f64Bytes[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  return f64View[0];
};

// decode each distinct token once
const huffFlat = new Array(huffTree.length * 2);
for (let i = 0; i < huffTree.length; i++) { huffFlat[i * 2] = huffTree[i][0]; huffFlat[i * 2 + 1] = huffTree[i][1]; }
const huffTag = new Array(huffTokens.length);
const huffVal = new Array(huffTokens.length);
for (let i = 0; i < huffTokens.length; i++) {
  const tok = huffTokens[i];
  const c = tok.charCodeAt(0);
  if (c === 64 || c === 66) { huffTag[i] = c; huffVal[i] = strings[parseInt(tok.slice(1), 36)]; } // @ B
  else if (c === 65 || c === 79) { huffTag[i] = c; huffVal[i] = parseInt(tok.slice(1), 36); } // A O
  else if (c === 68) { huffTag[i] = c; huffVal[i] = fromF64Hex(tok.slice(1)); } // D
  else if (c === 95 || c === 85 || c === 84 || c === 70) { huffTag[i] = c; huffVal[i] = 0; } // _ U T F
  else { huffTag[i] = 0; huffVal[i] = parseInt(tok, 36); }
}

const huffDecode = data => {
  const out = [];
  let node = 0;
  const split = data.indexOf(':');
  let bits = parseInt(data.slice(0, split), 36);
  for (let i = split + 1; bits > 0; i++) {
    const value = huffValue(data.charCodeAt(i));
    for (let shift = 5; shift >= 0 && bits > 0; shift--, bits--) {
      node = huffFlat[node * 2 + ((value >> shift) & 1)];
      if (node < 0) { out.push(-node - 1); node = 0; }
    }
  }
  return out;
};

const unflatten = cur => {
  const idx = cur.tokens[cur.i++];
  const tag = huffTag[idx];
  const v = huffVal[idx];
  if (tag === 0 || tag === 64 || tag === 68) return v; // int @ D
  if (tag === 65) { // A
    const a = new Array(v);
    for (let j = 0; j < v; j++) a[j] = unflatten(cur);
    return a;
  }
  if (tag === 79) { // O
    const o = {};
    for (let j = 0; j < v; j++) { const k = unflatten(cur); o[k] = unflatten(cur); }
    return o;
  }
  if (tag === 95) return null;
  if (tag === 85) return undefined;
  if (tag === 84) return true;
  if (tag === 70) return false;
  return BigInt(v); // B
};

// IR node kinds the dynamic walk cares about (mirrors ir.js K.*).
const K_DataRef = 2, K_Global = 4, K_TypeSwitch = 33, K_Call = 36, K_Alloc = 43, K_ThrowNew = 40, K_FuncIdx = 54, K_FuncRec = 55;

// is `v` an IR node array (defensive: length-6, numeric kind/type/fx)? a value-array such as a
// case tuple or a list of type ids fails this, and the per-kind guards below disambiguate the
// rare collision (e.g. a 6-long type-id list whose [0] equals a kind number).
const isNode = v => Array.isArray(v) && v.length === 6 && typeof v[0] === 'number' && typeof v[1] === 'number' && typeof v[2] === 'number';
const isComptimeFlag = v => v && typeof v === 'object' && !Array.isArray(v) && v.__porfComptimeFlag;
const resolveComptimeFlag = (h, kind, value) => kind === 'hasFunc' ? h.hasFunc(value) : h.usesAnyType([ value ]);

// the dynamic resolution pass walks the reconstructed IR tree, threading the codegen helpers `h`:
//   - live Call to a builtin       -> h.includeBuiltin(name)   (so it gets compiled + emitted)
//   - DataRef / Alloc / Global     -> h.remap* / h.global      (rebind to the user compile's arena)
//   - TypeSwitch case              -> deferred to h.onFinalize, gated on h.usesAnyType(typeIds)
//     when usedTypes is final, so a dead case's subtree is never walked (its builtins/strings are
//     never included -> never emitted), while a type first used by a later builtin still activates.
const walk = (node, h) => {
  if (isComptimeFlag(node)) return node;
  if (!isNode(node)) {
    if (Array.isArray(node)) {
      for (let i = 0; i < node.length; i++) {
        const x = node[i];
        if (isComptimeFlag(x)) {
          (h.onLateFinalize ?? h.onFinalize)(() => {
            const pos = node.indexOf(x);
            if (pos === -1) return;
            const [ kind, value, thenBranch, elseBranch ] = x.__porfComptimeFlag;
            const selected = resolveComptimeFlag(h, kind, value) ? thenBranch : elseBranch;
            node.splice(pos, 1, ...selected);
            for (let j = pos; j < pos + selected.length; j++) walk(node[j], h);
          });
        } else node[i] = walk(x, h);
      }
    }
    return node;
  }

  const kind = node[0];
  if (kind === K_TypeSwitch && Array.isArray(node[4]) && node[4].every(c => Array.isArray(c))) {
    walk(node[3], h); // subject is always live
    for (const c of node[4]) {
      const typeIds = c[0];
      let walkedCase = false;
      h.onFinalize(() => {
        if (walkedCase || !h.usesAnyType(typeIds)) return;
        walkedCase = true;
        for (let j = 1; j < c.length; j++) walk(c[j], h);
      });
    }
    walk(node[5], h); // default
    return node;
  }

  // bind by index: a user function sharing a builtin's name (eg an inner `resolve`) must not capture it
  if (kind === K_Call && typeof node[3] === 'string' && h.hasBuiltin(node[3])) node[3] = h.includeBuiltin(node[3]).index;
  // a throwable error type is usable: its accessors/toString must survive type gating
  else if (kind === K_ThrowNew) h.typeUsed(node[3]);
  else if (kind === K_DataRef) node[3] = h.remapData(node[3]);
  else if (kind === K_Alloc && Array.isArray(node[5])) node[5][0] = h.remapAllocSite(node[5][0]);
  else if (kind === K_FuncIdx || kind === K_FuncRec) {
    const f = h.includeBuiltin(node[3]);
    f.indirect = true;
    node[3] = f.index;
  }
  else if (kind === K_Global && typeof node[3] === 'string') h.global(node[3], node[1]);

  walk(node[3], h);
  walk(node[4], h);
  walk(node[5], h);
  return node;
};

const cloneIR = v => {
  if (Array.isArray(v)) {
    const a = new Array(v.length);
    for (let i = 0; i < v.length; i++) a[i] = cloneIR(v[i]);
    return a;
  }
  if (v !== null && typeof v === 'object') {
    const o = {};
    for (const k in v) o[k] = cloneIR(v[k]);
    return o;
  }
  return v;
};

// b(data) decodes a compressed IR body the first time it is read, then hands out a copy per read.
const b = data => {
  let tree;
  const out = h => {
    if (tree === undefined) tree = unflatten({ tokens: huffDecode(data), i: 0 });
    return walk(cloneIR(tree), h);
  };
  out.precompiled = true;
  return out;
};

// one record per builtin: [ name, body, meta, global, init, ... ].
